'use client'

import {Calendar as AstryxCalendar, type CalendarProps} from '@astryxdesign/core/Calendar'
import {pickerStyles} from './picker.styles'

export type QuestCalendarProps = CalendarProps
export type {DateRange, ISODateString, CalendarHandle} from '@astryxdesign/core/Calendar'

/** Native Astryx single/range selection and keyboard navigation, in Quest's pixel grid. */
export function Calendar({xstyle, ...props}: QuestCalendarProps) {
  return <AstryxCalendar {...props} xstyle={[pickerStyles.calendar, xstyle]} />
}

"use client"
import * as stylex from '@stylexjs/stylex'
import type {IndicatorProps} from '@astryxdesign/core/Indicator'
import {PixelIcon} from './pixel-icon'

const styles = stylex.create({
  box: {
    '--q-control-fill': 'var(--q-card)', '--q-control-ink': 'var(--q-card-foreground)',
    '--q-control-hover': {default: 'var(--q-control-fill)', ':hover': 'color-mix(in srgb,var(--q-control-fill),var(--q-foreground) 10%)'},
    position: 'relative', isolation: 'isolate', display: 'inline-flex', alignItems: 'center', justifyContent: 'center',
    boxSizing: 'border-box', flexShrink: 0, width: 44, height: 44, borderWidth: 0, borderRadius: 0,
    backgroundColor: 'transparent', color: 'var(--q-control-ink)', filter: 'drop-shadow(0 3px 0 var(--q-shadow))',
    '::before': {content: '""', position: 'absolute', inset: 0, zIndex: -1, pointerEvents: 'none', clipPath: 'var(--q-step)', backgroundColor: 'var(--q-edge)'},
    '::after': {content: '""', position: 'absolute', inset: 3, zIndex: -1, pointerEvents: 'none', clipPath: 'var(--q-step)', backgroundColor: 'var(--q-control-hover)', boxShadow: 'inset 0 3px 0 color-mix(in srgb,var(--q-control-fill),white 20%),inset 0 -3px 0 color-mix(in srgb,var(--q-control-fill),black 18%)'},
    '@media (forced-colors: active)': {borderWidth: 2, borderStyle: 'solid', borderColor: 'ButtonText', backgroundColor: 'Canvas', color: 'CanvasText', filter: 'none', '::before': {display: 'none'}, '::after': {display: 'none'}},
  },
  checked: {'--q-control-fill': 'var(--q-primary)', '--q-control-ink': 'var(--q-primary-foreground)',
    '@media (forced-colors: active)': {forcedColorAdjust: 'none', backgroundColor: 'Highlight', color: 'HighlightText'}},
  disabled: {opacity: 0.45, cursor: 'not-allowed', '@media (forced-colors: active)': {opacity: 1, color: 'GrayText', borderColor: 'GrayText'}},
  dash: {width: 20, height: 4, backgroundColor: 'currentColor'},
  mark: {display: 'inline-flex', alignItems: 'center', justifyContent: 'center', width: 16, height: 16, color: 'inherit', flexShrink: 0},
})

export function PixelCheckboxIndicator({state, size: _size, isDisabled, children, xstyle, className, style, ...props}: IndicatorProps<'multiSelection'>) {
  const visual = stylex.props(styles.box, state !== 'unchecked' && styles.checked, isDisabled && styles.disabled, xstyle)
  return <span {...props} {...visual} className={[visual.className, className].filter(Boolean).join(' ')} style={{...visual.style, ...style}} aria-hidden="true">
    {children ?? (state === 'indeterminate' ? <span {...stylex.props(styles.dash)}/> : state === 'checked' ? <PixelIcon name="check" width={20} height={20}/> : null)}
  </span>
}

export function PixelRadioIndicator({state, children, ...props}: IndicatorProps<'singleSelection'>) {
  return <PixelCheckboxIndicator {...props} state={state}>{children ?? (state === 'checked' ? <PixelIcon name="diamond" width={20} height={20}/> : null)}</PixelCheckboxIndicator>
}

export function PixelSelectionIndicator({state, size: _size, isDisabled: _disabled, children, xstyle, className, style, ...props}: IndicatorProps<'singleSelection'>) {
  const visual = stylex.props(styles.mark, xstyle)
  return <span {...props} {...visual} className={[visual.className, className].filter(Boolean).join(' ')} style={{...visual.style, ...style}} aria-hidden="true">{children ?? (state === 'checked' ? <PixelIcon name="check"/> : null)}</span>
}

export const questIndicators = {checkbox: PixelCheckboxIndicator, radio: PixelRadioIndicator, check: PixelSelectionIndicator}

/** Quest pixel overrides for Astryx internal control targets; merge into defineTheme({components}). */
export const questControlTargets = {
  'switch': {
    base: {
      borderRadius: '0',
      backgroundColor: 'var(--q-muted)',
      boxShadow: 'inset 0 3px 0 color-mix(in srgb, var(--q-card), white 0%), inset 0 0 0 3px var(--q-edge), inset 0 -3px 0 color-mix(in srgb, var(--q-muted), black 18%)',
      ':checked': {backgroundColor: 'var(--q-primary)'},
      ':focus-visible': {outline: '3px solid var(--q-ring)', outlineOffset: '4px'},
    },
    checked: {backgroundColor: 'var(--q-primary)'},
    disabled: {opacity: '0.45'},
  },
  'switch-thumb': {
    base: {
      borderRadius: '0',
      clipPath: 'var(--q-step)',
      backgroundColor: 'var(--q-foreground)',
      boxShadow: 'inset 0 -4px 0 var(--q-edge)',
      '@media (forced-colors: active)': {backgroundColor: 'ButtonText', boxShadow: 'none', clipPath: 'none'},
    },
    checked: {backgroundColor: 'var(--q-primary-foreground)', '@media (forced-colors: active)': {backgroundColor: 'HighlightText'}},
  },
  'slider': {base: {}},
  'slider-track': {
    base: {
      borderRadius: '0',
      backgroundColor: 'var(--q-muted)',
      boxShadow: 'inset 0 0 0 3px var(--q-edge)',
      ':focus-visible': {outline: 'none'},
      '@media (forced-colors: active)': {backgroundColor: 'Canvas', boxShadow: 'inset 0 0 0 2px ButtonText'},
    },
  },
  'slider-thumb': {
    base: {
      borderRadius: '0',
      clipPath: 'var(--q-step)',
      backgroundColor: 'var(--q-primary)',
      filter: 'drop-shadow(0 3px 0 var(--q-shadow))',
      cursor: 'grab',
      ':active': {cursor: 'grabbing'},
      ':focus-visible': {outline: '3px solid var(--q-ring)', outlineOffset: '4px'},
      '@media (forced-colors: active)': {borderRadius: '0', clipPath: 'none', backgroundColor: 'Highlight', filter: 'none'},
    },
  },
  'selector': {
    base: {
      paddingBlock: '10px',
      paddingInline: '16px',
      borderRadius: '0',
      borderWidth: '0',
      backgroundColor: 'transparent',
      filter: 'drop-shadow(0 3px 0 var(--q-shadow))',
      fontFamily: 'var(--q-font-display)',
      fontSize: '20px',
      lineHeight: '1.3',
      '@media (forced-colors: active)': {filter: 'none', border: '2px solid ButtonText', backgroundColor: 'Canvas'},
    },
    'size:sm': {paddingBlock: '8px', paddingInline: '12px', fontSize: '18px'},
  },
  'selector-popup': {
    base: {
      borderRadius: '0',
      borderWidth: '3px',
      borderStyle: 'solid',
      borderColor: 'var(--q-edge)',
      backgroundColor: 'var(--q-popover)',
      color: 'var(--q-popover-foreground)',
      fontFamily: 'var(--q-font-body)',
      fontSize: '22px',
      padding: '6px',
      '@media (forced-colors: active)': {border: '2px solid ButtonText', backgroundColor: 'Canvas', color: 'CanvasText', boxShadow: 'none'},
    },
  },
  'selector-option-row': {
    base: {
      minHeight: '44px',
      paddingBlock: '8px',
      paddingInline: '12px',
      borderRadius: '0',
      clipPath: 'var(--q-step)',
      cursor: 'default',
      ':hover': {backgroundColor: 'color-mix(in srgb, var(--q-card), var(--q-foreground) 10%)'},
      '@media (forced-colors: active)': {clipPath: 'none'},
    },
    selected: {
      backgroundColor: 'var(--q-accent)',
      color: 'var(--q-accent-foreground)',
      boxShadow: 'inset 0 0 0 2px var(--q-ring)',
      '@media (forced-colors: active)': {forcedColorAdjust: 'none', backgroundColor: 'Highlight', color: 'HighlightText'},
    },
    disabled: {opacity: '0.45', pointerEvents: 'none'},
  },
  'selector-section-heading': {
    base: {fontFamily: 'var(--q-font-display)', fontSize: '20px', fontVariant: 'small-caps', fontWeight: '700', color: 'var(--q-muted-foreground)', paddingBlock: '8px', paddingInline: '12px'},
  },
  'selector-indicator-icon': {
    base: {width: '16px', height: '16px'},
    expanded: {transform: 'rotate(180deg)'},
  },
  'checkbox-indicator': {
    base: {},
    checked: {}, indeterminate: {}, disabled: {},
  },
  'radio-indicator': {base: {}, checked: {}, disabled: {}},
} as const

import {createElement} from 'react'
import type {ComponentStyleMap} from '@astryxdesign/core/theme'
import * as stylex from '@stylexjs/stylex'
import {PixelIcon} from './pixel-icon'

const frame = {
  position: 'relative', isolation: 'isolate', boxSizing: 'border-box',
  borderWidth: '0px', borderRadius: '0px', backgroundColor: 'transparent',
  boxShadow: 'none', filter: 'drop-shadow(4px 4px 0 var(--q-shadow))',
  color: 'var(--q-popover-foreground)', fontFamily: 'var(--q-font-body)',
  fontSize: '18px', lineHeight: '1.4',
  '::before': {
    content: '""', position: 'absolute', inset: '0px', zIndex: '-1',
    pointerEvents: 'none', clipPath: 'var(--q-step)', backgroundColor: 'var(--q-highlight)',
  },
  '::after': {
    content: '""', position: 'absolute', inset: '3px', zIndex: '-1',
    pointerEvents: 'none', clipPath: 'var(--q-step)', backgroundColor: 'var(--q-popover)',
    boxShadow: 'inset 0 4px 0 var(--q-border)',
  },
}

/** Public Astryx targets only; private calendar slots inherit scoped tokens. */
export const pickerThemeComponents: ComponentStyleMap = {
  popover: {base: frame},
  'calendar-nav': {
    base: {
      width: '48px', height: '48px', minHeight: '48px', padding: '12px',
      borderWidth: '0px', borderRadius: '0px', boxShadow: 'none',
      backgroundColor: 'transparent', color: 'var(--q-foreground)',
      ':hover': {backgroundColor: 'var(--q-accent)', color: 'var(--q-accent-foreground)'},
      ':focus-visible': {outline: '3px solid var(--q-ring)', outlineOffset: '-3px'},
    },
    'disabled:disabled': {opacity: '.45', cursor: 'not-allowed'},
  },
  'calendar-day': {
    base: {
      width: '100%', minWidth: '44px', height: '44px', padding: '4px',
      border: '3px solid transparent', borderRadius: '0px', boxShadow: 'none',
      backgroundColor: 'transparent', backgroundImage: 'none',
      color: 'var(--q-foreground)', fontFamily: 'var(--q-font-body)',
      fontSize: '20px', lineHeight: '1.2', transition: 'none',
      ':hover': {backgroundColor: 'var(--q-accent)', color: 'var(--q-accent-foreground)', outline: '2px solid var(--q-ring)', outlineOffset: '-2px'},
      ':focus-visible': {outline: '3px solid var(--q-ring)', outlineOffset: '-3px'},
    },
    'in-range:in-range': {backgroundColor: 'var(--q-accent)', color: 'var(--q-accent-foreground)'},
    'today:today': {
      backgroundColor: 'var(--q-accent)', color: 'var(--q-accent-foreground)', boxShadow: 'none',
      '::after': {content: '""', position: 'absolute', bottom: '3px', width: '12px', height: '3px', backgroundColor: 'currentColor'},
    },
    'selected:selected': {
      backgroundColor: 'var(--q-primary)', color: 'var(--q-primary-foreground)',
      borderColor: 'var(--q-edge)', boxShadow: 'inset 0 -3px 0 color-mix(in srgb,var(--q-primary),black 25%)',
    },
    'disabled:disabled': {opacity: '.45', cursor: 'not-allowed'},
  },
  'selector-popup': {
    base: {
      ...frame, padding: '8px', minWidth: '240px',
      '--color-text-primary': 'var(--q-popover-foreground)',
      '--color-text-secondary': 'var(--q-muted-foreground)',
      '--color-overlay-hover': 'var(--q-accent)',
      '--color-accent': 'var(--q-ring)',
      '--text-label-size': '18px', '--font-family-body': 'var(--q-font-body)',
      '--radius-element': '0px', '--radius-container': '0px',
      '--focus-outline-width': '3px', '--focus-outline-color': 'var(--q-ring)',
    },
  },
  'selector-search': {
    base: {
      boxSizing: 'border-box', minHeight: '44px', padding: '8px',
      border: '2px solid transparent', borderRadius: '0px',
      color: 'var(--q-popover-foreground)', fontFamily: 'var(--q-font-body)',
      fontSize: '18px', lineHeight: '1.4', backgroundColor: 'transparent',
      ':focus-visible': {borderColor: 'var(--q-ring)'},
      '::placeholder': {color: 'var(--q-muted-foreground)', opacity: '1'},
    },
  },
  'selector-option-row': {
    base: {
      minHeight: '44px', padding: '8px', border: '2px solid transparent',
      borderRadius: '0px', fontFamily: 'var(--q-font-body)', fontSize: '18px',
      color: 'var(--q-popover-foreground)',
      ':hover': {borderColor: 'var(--q-ring)', backgroundColor: 'var(--q-accent)', color: 'var(--q-accent-foreground)'},
      ':focus-visible': {outline: '3px solid var(--q-ring)', outlineOffset: '-3px'},
    },
    'selected:selected': {fontWeight: '700'},
    'disabled:disabled': {opacity: '.45', cursor: 'not-allowed'},
  },
  'selector-section-heading': {
    base: {padding: '8px', color: 'var(--q-muted-foreground)', fontFamily: 'var(--q-font-display)', fontSize: '14px', fontWeight: '700'},
  },
  'selector-empty-state': {
    base: {padding: '24px 12px', color: 'var(--q-muted-foreground)', fontFamily: 'var(--q-font-body)', fontSize: '18px', textAlign: 'center'},
  },
  'selector-indicator-icon': {base: {width: '16px', height: '16px', color: 'var(--q-foreground)', transition: 'none'}},
}

const iconStyles = stylex.create({
  left: {transform: 'rotate(180deg)'},
  down: {transform: 'rotate(90deg)'},
})

export const pickerThemeIcons = {
  chevronLeft: createElement(PixelIcon, {name: 'arrow', ...stylex.props(iconStyles.left)}),
  chevronRight: createElement(PixelIcon, {name: 'arrow'}),
  chevronDown: createElement(PixelIcon, {name: 'arrow', ...stylex.props(iconStyles.down)}),
}
